import { Box, Button, Card, CardContent, Typography, Avatar, AvatarGroup, useTheme, useMediaQuery } from "@mui/material"
import PropTypes from "prop-types"

export const PaymentOption = ({ Icon, title, description, onClick, showDescription, showAvatar = true }) => {
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down("md"))
    const isTablet = useMediaQuery(theme.breakpoints.down("sm"))

    // Determine if description should be shown based on breakpoints
    const shouldShowDescription =
        typeof showDescription === "object"
            ? isMobile
                ? showDescription.xs
                : isTablet
                    ? showDescription.sm
                    : showDescription.md
            : showDescription

    const mockAvatars = [
        { id: 1, name: "John D", src: "/placeholder.svg?height=32&width=32" },
        { id: 2, name: "Jane S", src: "/placeholder.svg?height=32&width=32" },
        { id: 3, name: "Mike R", src: "/placeholder.svg?height=32&width=32" },
    ]

    return (
        <Card
            sx={{
                backgroundColor: "rgba(26, 27, 30, 0.8)",
                backdropFilter: "blur(10px)",
                border: "1px solid rgba(255, 255, 255, 0.1)",
                borderRadius: 2,
                height: "100%",
                padding:"1px 1px 1px 1px"
            }}
        >
            <CardContent sx={{ height: "100%", display: "flex", flexDirection: "column", justifyContent: "space-between" ,          p: "16px", // Set all sides to 16px
                "&:last-child": {
                    p: { xs: "10px", sm: "24px" },  // Override the bottom padding for the last child
                },}}>
                <Box>
                    <Box sx={{ display: "flex", alignItems: "center", mb: { xs: 1, sm: 2 } }}>
                        <Icon size={24} color="#2DD4BF" />

                        {shouldShowDescription && (
                            <Typography variant={{ xs: "body2", md: "body1" }} sx={{ color: "rgba(255, 255, 255, 0.7)", ml: 1 }}>
                                {description}
                            </Typography>
                        )}


                    {showAvatar && (
                        <AvatarGroup
                            max={3}
                            spacing="small"
                            sx={{
                                flexDirection: "row-reverse",
                                "& .MuiAvatar-root": {
                                    width: 25,
                                    height: 25,
                                    fontSize: "0.875rem",
                                    bgcolor: "#2DD4BF",
                                    border: "2px solid rgba(26, 27, 30, 0.8)",
                                },
                                "& .MuiAvatarGroup-avatar": {
                                    marginLeft: -2.5, // Negative margin for tighter grouping
                                    borderWidth: 2, // Ensure border is visible
                                },
                                mt: shouldShowDescription ? 0 : 0.5,
                                ml:8
                            }}

                        >
                            {mockAvatars.map((avatar) => (
                                <Avatar key={avatar.id} src={avatar.src} alt={avatar.name}>
                                    {avatar.name[0]}
                                </Avatar>
                            ))}
                        </AvatarGroup>
                    )}
                    </Box>
                </Box>

                <Button
                    variant="contained"
                    onClick={onClick}
                    sx={{
                        bgcolor: "#2DD4BF",
                        color: "black",
                        "&:hover": {
                            bgcolor: "rgba(45, 212, 191, 0.8)",
                        },
                    }}
                >
                    {title}
                </Button>
            </CardContent>
        </Card>
    )
}

PaymentOption.propTypes = {
    Icon: PropTypes.elementType.isRequired,
    title: PropTypes.string.isRequired,
    description: PropTypes.string.isRequired,
    onClick: PropTypes.func.isRequired,
    showDescription: PropTypes.oneOfType([
        PropTypes.bool,
        PropTypes.shape({
            xs: PropTypes.bool,
            sm: PropTypes.bool,
            md: PropTypes.bool,
        }),
    ]),
    showAvatar: PropTypes.bool,
}

