 const GroupDialog = ({ open, onClose }) => {
    const [groupName, setGroupName] = React.useState("")
    const friends = [
        { id: 1, name: "John Doe", avatar: "/placeholder.svg?height=40&width=40" },
        { id: 2, name: "Jane Smith", avatar: "/placeholder.svg?height=40&width=40" },
        { id: 3, name: "Alice Johnson", avatar: "/placeholder.svg?height=40&width=40" },
    ]

    return (
        <Dialog open={open} onClose={onClose} fullScreen sx={mobileDialogStyles}>
            <DialogTitle
                sx={{
                    color: "white",
                    borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
                    display: "flex",
                    alignItems: "center",
                    gap: 2,
                    px: 2,
                    py: 1.5,
                }}
            >
                <IconButton edge="start" onClick={onClose} sx={{ color: "white" }}>
                    <ArrowLeft />
                </IconButton>

                <Typography variant="h6">Create Group</Typography>
            </DialogTitle>

            <DialogContent sx={{ p: 2 }}>
                <TextField
                    fullWidth
                    label="Group Name"
                    value={groupName}
                    onChange={(e) => setGroupName(e.target.value)}
                    sx={{
                        mt: 2,
                        mb: 3,
                        "& .MuiOutlinedInput-root": {
                            color: "white",
                            "& fieldset": { borderColor: "rgba(255, 255, 255, 0.1)" },
                            "&:hover fieldset": { borderColor: "#2DD4BF" },
                            "&.Mui-focused fieldset": { borderColor: "#2DD4BF" },
                        },
                        "& .MuiInputLabel-root": {
                            color: "rgba(255, 255, 255, 0.7)",
                            "&.Mui-focused": { color: "#2DD4BF" },
                        },
                    }}
                />

                <Typography variant="subtitle2" sx={{ color: "rgba(255, 255, 255, 0.7)", mb: 2 }}>
                    Select Members
                </Typography>

                <List
                    sx={{
                        bgcolor: "rgba(255, 255, 255, 0.03)",
                        borderRadius: 1,
                    }}
                >
                    {friends.map((friend) => (
                        <ListItem
                            key={friend.id}
                            sx={{
                                borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
                                "&:last-child": {
                                    borderBottom: "none",
                                },
                            }}
                        >
                            <ListItemIcon>
                                <Avatar src={friend.avatar} sx={{ bgcolor: "#2DD4BF" }}>
                                    {friend.name.charAt(0)}
                                </Avatar>
                            </ListItemIcon>

                            <ListItemText
                                primary={friend.name}
                                sx={{
                                    "& .MuiListItemText-primary": { color: "white" },
                                }}
                            />
                        </ListItem>
                    ))}
                </List>
            </DialogContent>

            <DialogActions
                sx={{
                    p: 2,
                    position: "sticky",
                    bottom: 0,
                }}
            >
                <Button
                    fullWidth
                    variant="contained"
                    onClick={onClose}
                    sx={{
                        bgcolor: "#2DD4BF",
                        color: "black",
                        py: 1.5,
                        "&:hover": {
                            bgcolor: "#26b5a3",
                        },
                    }}
                >
                    Confirm
                </Button>
            </DialogActions>
        </Dialog>
    )
}

