import { useState } from "react"
import { useSelector, useDispatch } from "react-redux"
import { Box, Typography, Avatar, Button, Dialog, DialogTitle, DialogContent, DialogActions } from "@mui/material"
import { Edit } from "@mui/icons-material"
import SettingSection from "./SettingSection"
import { updateAvatar } from "../../../store/redux/authReducer"

const AvatarSettingCard = () => {
    const [open, setOpen] = useState(false)
    const dispatch = useDispatch()
    const avatarUrl = useSelector((state) => state.auth.user.avatar)

    const handleOpen = () => setOpen(true)
    const handleClose = () => setOpen(false)

    const handleAvatarChange = (event) => {
        const file = event.target.files[0]

        if (file) {
            const reader = new FileReader()

            reader.onloadend = () => {
                dispatch(updateAvatar(reader.result))
            }

            reader.readAsDataURL(file)
        }

        handleClose()
    }

    return (
        <>
            <SettingSection title="Profile Picture">
                <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                    <Avatar src={avatarUrl} alt="User Avatar" sx={{ width: 80, height: 80, mr: 2 }} />

                    <Button
                        variant="outlined"
                        startIcon={<Edit />}
                        onClick={handleOpen}
                        sx={{
                            color: "white",
                            borderColor: "rgba(255, 255, 255, 0.1)",
                            "&:hover": {
                                borderColor: "#2DD4BF",
                                backgroundColor: "rgba(45, 212, 191, 0.1)",
                            },
                        }}
                    >
                        Change Avatar
                    </Button>
                </Box>
            </SettingSection>

            <Dialog
                open={open}
                onClose={handleClose}
                PaperProps={{
                    style: {
                        backgroundColor: "rgba(26, 27, 30, 0.95)",
                        backdropFilter: "blur(10px)",
                        border: "1px solid rgba(255, 255, 255, 0.1)",
                    },
                }}
            >
                <DialogTitle sx={{ color: "white" }}>Change Profile Picture</DialogTitle>

                <DialogContent>
                    <Typography sx={{ color: "rgba(255, 255, 255, 0.7)", mb: 2 }}>
                        Select a new image for your profile picture
                    </Typography>

                    <input
                        accept="image/*"
                        style={{ display: "none" }}
                        id="raised-button-file"
                        type="file"
                        onChange={handleAvatarChange}
                    />

                    <label htmlFor="raised-button-file">
                        <Button
                            variant="contained"
                            component="span"
                            sx={{
                                bgcolor: "#2DD4BF",
                                color: "#1A1B1E",
                                "&:hover": {
                                    bgcolor: "#26b5a3",
                                },
                            }}
                        >
                            Upload New Picture
                        </Button>
                    </label>
                </DialogContent>

                <DialogActions>
                    <Button onClick={handleClose} sx={{ color: "rgba(255, 255, 255, 0.7)" }}>
                        Cancel
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    )
}

export default AvatarSettingCard

