import { useState } from "react"
import PropTypes from "prop-types"
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField,
    Button,
    Box,
    Typography,
    IconButton,
    InputAdornment,
} from "@mui/material"
import { ArrowLeft, DollarSign } from "lucide-react"
import EmojiInputBox from "../../../components/payments/EmojiInputBox"

const RequestMoneyDialog = ({ open, onClose, onRequestMoney }) => {
    const [request, setRequest] = useState({
        from: "",
        amount: "",
        description: "",
    })

    const handleChange = (e) => {
        const { name, value } = e.target
        setRequest((prev) => ({ ...prev, [name]: value }))
    }

    const handleRequestMoney = () => {
        onRequestMoney(request)
        setRequest({ from: "", amount: "", description: "" })
        onClose()
    }

    return (
        <Dialog
            open={open}
            onClose={onClose}
            fullScreen
            PaperProps={{
                sx: {
                    margin: { xs: 0, sm: 32 },
                    maxHeight: { xs: "100%", sm: "calc(100% - 64px)" },
                    height: { xs: "100%", sm: "auto" },
                    borderRadius: { xs: 0, sm: 2 },
                    backgroundColor: "rgba(26, 27, 30, 0.95)",
                    backdropFilter: "blur(10px)",
                    border: "1px solid rgba(255, 255, 255, 0.1)",
                },
            }}
        >
            <DialogTitle
                sx={{
                    color: "white",
                    borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
                    display: "flex",
                    alignItems: "center",
                    gap: 2,
                    px: 2,
                    py: 1.5,
                }}
            >
                <IconButton edge="start" onClick={onClose} sx={{ color: "white" }}>
                    <ArrowLeft />
                </IconButton>

                <Typography variant="h6">Request Money</Typography>
            </DialogTitle>

            <DialogContent sx={{ p: 2 }}>
                <Box sx={{ mt: 2 }}>
                    <TextField
                        autoFocus
                        margin="dense"
                        name="from"
                        label="Request From"
                        type="text"
                        fullWidth
                        value={request.from}
                        onChange={handleChange}
                        sx={{
                            mb: 2,
                            "& .MuiOutlinedInput-root": {
                                color: "white",
                                "& fieldset": { borderColor: "rgba(255, 255, 255, 0.1)" },
                                "&:hover fieldset": { borderColor: "#2DD4BF" },
                                "&.Mui-focused fieldset": { borderColor: "#2DD4BF" },
                            },
                            "& .MuiInputLabel-root": {
                                color: "rgba(255, 255, 255, 0.7)",
                                "&.Mui-focused": { color: "#2DD4BF" },
                            },
                        }}
                    />

                    <TextField
                        margin="dense"
                        name="amount"
                        label="Amount"
                        type="number"
                        fullWidth
                        value={request.amount}
                        onChange={handleChange}
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <DollarSign size={20} color="#2DD4BF" />
                                </InputAdornment>
                            ),
                        }}
                        sx={{
                            mb: 2,
                            "& .MuiOutlinedInput-root": {
                                color: "white",
                                "& fieldset": { borderColor: "rgba(255, 255, 255, 0.1)" },
                                "&:hover fieldset": { borderColor: "#2DD4BF" },
                                "&.Mui-focused fieldset": { borderColor: "#2DD4BF" },
                            },
                            "& .MuiInputLabel-root": {
                                color: "rgba(255, 255, 255, 0.7)",
                                "&.Mui-focused": { color: "#2DD4BF" },
                            },
                        }}
                    />

                    <EmojiInputBox onInputChange={() => {}} placeholder="Note (Optional)" />
                </Box>
            </DialogContent>

            <DialogActions
                sx={{
                    p: 2,
                    position: "sticky",
                    bottom: 0,
                }}
            >
                <Button
                    fullWidth
                    variant="contained"
                    onClick={handleRequestMoney}
                    sx={{
                        bgcolor: "#2DD4BF",
                        color: "black",
                        py: 1.5,
                        "&:hover": {
                            bgcolor: "#26b5a3",
                        },
                    }}
                >
                    Request Money
                </Button>
            </DialogActions>
        </Dialog>
    )
}

RequestMoneyDialog.propTypes = {
    open: PropTypes.bool.isRequired,
    onClose: PropTypes.func.isRequired,
    onRequestMoney: PropTypes.func.isRequired,
}

export default RequestMoneyDialog

