import React, { useEffect, useState } from "react"
import PropTypes from "prop-types"
import {
    Box,
    Container,
    Typography,
    Card,
    CardContent,
    List,
    ListItem,
    ListItemText,
    Divider,
    IconButton,
} from "@mui/material"
import { Bell, CreditCard, DollarSign, UserPlus, Menu } from "lucide-react"
import Sidebar from "../Dashboard/components/Sidebar"
import NotificationDialog from "./components/NotificationDialog"
import { useSelector } from "react-redux"
import notificationService from "../../api/notification";

const NotificationIcon = ({ type }) => {
    const icons = {
        payment: DollarSign,
        card: CreditCard,
        friend: UserPlus,
    }
    const Icon = icons[type] || Bell

    return (
        <Box
            sx={{
                width: 40,
                height: 40,
                borderRadius: "50%",
                backgroundColor: "rgba(45, 212, 191, 0.1)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                mr: 2,
            }}
        >
            <Icon size={20} color="#2DD4BF" />
        </Box>
    )
}

NotificationIcon.propTypes = {
    type: PropTypes.oneOf(["payment", "card", "friend", "general"]).isRequired,
}

// Mock data
const mockNotifications = [
    {
        id: 1,
        content: "Your payment of $50 has been processed",
        createdAt: "2023-05-15T10:30:00Z",
        type: "payment",
        isPinned: true,
    },
    {
        id: 2,
        content: "New card added to your account",
        createdAt: "2023-05-14T14:45:00Z",
        type: "card",
        isPinned: false,
    },
    {
        id: 3,
        content: "John Doe sent you a friend request",
        createdAt: "2023-05-16T09:15:00Z",
        type: "friend",
        isPinned: true,
    },
    {
        id: 4,
        content: "Your subscription will renew in 3 days",
        createdAt: "2023-05-13T11:00:00Z",
        type: "general",
        isPinned: false,
    },
    {
        id: 5,
        content: "Security alert: New login detected",
        createdAt: "2023-05-16T08:30:00Z",
        type: "general",
        isPinned: false,
    },
]

const NotificationsPage = ({ mobileOpen, handleDrawerToggle, isFullscreen }) => {
    const [notifications, setNotifications] = useState([])
    const [selectedNotification, setSelectedNotification] = useState(null)
    const [dialogOpen, setDialogOpen] = useState(false)
    const userId = useSelector((state) => state.auth?.user?.id || "5137654321")
    const service=new notificationService.constructor(useSelector(state => state.auth.user))
    useEffect(() => {
        service.connect(userId)
        const unsubscribe = service.subscribe((newNotification) => {
            setNotifications((prev) => [newNotification, ...prev])
        })

        return () => {
            unsubscribe()
            service.disconnect()
        }
    }, [userId])
    useEffect(() => {
        const fetchNotifications = async () => {
            try {

                const allNotifications = await service.getNotices()
                setNotifications((prev) => [...allNotifications, ...prev])
            } catch (error) {
                console.error("Failed to fetch notifications:", error)
            }
        }

        fetchNotifications()
        setNotifications(mockNotifications)
    }, [])


    // Sort notifications: pinned first, then by creation date
    const sortedNotifications = [...notifications].sort((a, b) => {
        if (a.isPinned && !b.isPinned) return -1
        if (!a.isPinned && b.isPinned) return 1
        return new Date(b.createdAt) - new Date(a.createdAt)
    })

    return (
        <Box sx={{ display: "flex" }}>
            <Sidebar mobileOpen={mobileOpen} handleDrawerToggle={handleDrawerToggle} />

            <Box
                component="main"
                sx={{
                    flexGrow: 1,
                    minHeight: "100vh",
                    backgroundColor: "#1A1B1E",
                    ml: { sm: "240px" },
                    width: { sm: `calc(100% - 240px)` },
                    py: 3,
                }}
            >
                <Container maxWidth="xl">
                    <Box sx={{ display: "flex", alignItems: "center", mb: 4 }}>
                        <IconButton
                            color="inherit"
                            aria-label="open drawer"
                            edge="start"
                            onClick={handleDrawerToggle}
                            sx={{ mr: 2, display: { sm: "none" } }}
                        >
                            <Menu />
                        </IconButton>

                        <Typography variant="h4" sx={{ color: "white" }}>
                            Notifications
                        </Typography>
                    </Box>

                    <Card
                        sx={{
                            backgroundColor: "rgba(26, 27, 30, 0.8)",
                            backdropFilter: "blur(10px)",
                            border: "1px solid rgba(255, 255, 255, 0.1)",
                            borderRadius: 2,
                        }}
                    >
                        <CardContent>
                            <List sx={{ py: 0 }}>
                                {sortedNotifications.length === 0 ? (
                                    <ListItem>
                                        <Typography sx={{ color: "white" }}>No notifications yet</Typography>
                                    </ListItem>
                                ) : (
                                    sortedNotifications.map((notification, index) => (
                                        <React.Fragment key={notification.id}>
                                            <ListItem
                                                sx={{
                                                    py: 2,
                                                    px: 3,
                                                    backgroundColor: notification.isPinned ? "rgba(45, 212, 191, 0.1)" : "transparent",
                                                    "&:hover": {
                                                        backgroundColor: "rgba(45, 212, 191, 0.1)",
                                                        cursor: "pointer",
                                                    },
                                                }}
                                                onClick={() => {
                                                    setSelectedNotification(notification)
                                                    setDialogOpen(true)
                                                }}
                                            >
                                                <NotificationIcon type={notification.type} />

                                                <ListItemText
                                                    primary={
                                                        <Box sx={{ display: "flex", alignItems: "center" }}>
                                                            <Typography
                                                                variant="subtitle1"
                                                                sx={{
                                                                    color: "white",
                                                                    fontWeight: notification.isPinned ? 600 : 400,
                                                                    mb: 0.5,
                                                                }}
                                                            >
                                                                {notification.content}
                                                            </Typography>

                                                            {notification.isPinned && (
                                                                <Box
                                                                    sx={{
                                                                        ml: 1,
                                                                        px: 1,
                                                                        py: 0.5,
                                                                        bgcolor: "rgba(45, 212, 191, 0.2)",
                                                                        borderRadius: 1,
                                                                        fontSize: "0.75rem",
                                                                    }}
                                                                >
                                                                    Pinned
                                                                </Box>
                                                            )}
                                                        </Box>
                                                    }
                                                    secondary={
                                                        <Typography
                                                            variant="caption"
                                                            sx={{
                                                                color: "rgba(255, 255, 255, 0.5)",
                                                            }}
                                                        >
                                                            {new Date(notification.createdAt).toLocaleString()}
                                                        </Typography>
                                                    }
                                                />
                                            </ListItem>

                                            {index < sortedNotifications.length - 1 && (
                                                <Divider sx={{ backgroundColor: "rgba(255, 255, 255, 0.1)" }} />
                                            )}
                                        </React.Fragment>
                                    ))
                                )}
                            </List>
                        </CardContent>
                    </Card>

                    <NotificationDialog
                        open={dialogOpen}
                        onClose={() => setDialogOpen(false)}
                        notification={selectedNotification}
                    />
                </Container>
            </Box>
        </Box>
    )
}

NotificationsPage.propTypes = {
    mobileOpen: PropTypes.bool.isRequired,
    handleDrawerToggle: PropTypes.func.isRequired,
    isFullscreen: PropTypes.bool.isRequired,
}

export default NotificationsPage

