import { useState, useRef } from "react"
import { Box, Typography } from "@mui/material"
import { ArrowUp, Trash2 } from "lucide-react"
import PropTypes from "prop-types"

const NotificationItem = ({ notification, onDelete, onFavorite }) => {
    const [isDragging, setIsDragging] = useState(false)
    const [startX, setStartX] = useState(0)
    const [currentTranslate, setCurrentTranslate] = useState(0)
    const elementRef = useRef(null)
    const swipeThreshold = 80

    const handleTouchStart = (e) => {
        setIsDragging(true)
        setStartX(e.touches[0].clientX - currentTranslate)

        if (elementRef.current) {
            elementRef.current.style.transition = "none"
        }
    }

    const handleTouchMove = (e) => {
        if (!isDragging) return
        const currentX = e.touches[0].clientX
        const translate = currentX - startX
        const bounded = Math.min(Math.max(translate, -100), 100)

        if (elementRef.current) {
            elementRef.current.style.transform = `translateX(${bounded}px)`
        }

        setCurrentTranslate(bounded)
    }

    const handleTouchEnd = () => {
        setIsDragging(false)
        if (!elementRef.current) return

        // Immediately reset position
        elementRef.current.style.transition = "transform 0.1s ease"
        elementRef.current.style.transform = "translateX(0)"
        setCurrentTranslate(0)

        // Handle action if threshold was met
        if (Math.abs(currentTranslate) >= swipeThreshold) {
            if (currentTranslate > 0) {
                onFavorite(notification.id)
            } else {
                onDelete(notification.id)
            }
        }
    }

    const rightActionOpacity = Math.min(Math.max(currentTranslate / swipeThreshold, 0), 1)
    const leftActionOpacity = Math.min(Math.max(-currentTranslate / swipeThreshold, 0), 1)

    return (
        <Box sx={{ position: "relative", overflow: "hidden" }}>
            {/* Action indicators */}
            <Box
                sx={{
                    position: "absolute",
                    right: 0,
                    top: 0,
                    bottom: 0,
                    width: 100,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    backgroundColor: "rgba(45, 212, 191, 0.1)",
                    opacity: rightActionOpacity,
                }}
            >
                <ArrowUp size={20} color="#2DD4BF" />
            </Box>

            <Box
                sx={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    bottom: 0,
                    width: 100,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    backgroundColor: "rgba(239, 68, 68, 0.1)",
                    opacity: leftActionOpacity,
                }}
            >
                <Trash2 size={20} color="#ef4444" />
            </Box>

            {/* Notification content */}
            <Box
                ref={elementRef}
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
                sx={{
                    position: "relative",
                    backgroundColor: notification.isRead ? "transparent" : "rgba(45, 212, 191, 0.05)",
                    borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
                    zIndex: 1,
                    touchAction: "pan-y",
                    py: { xs: 1, sm: 2 },
                    px: 2,
                    minHeight: { xs: "60px", sm: "auto" },
                    transform: "translateX(0)",
                    willChange: "transform",
                    WebkitBackfaceVisibility: "hidden",
                    WebkitPerspective: 1000,
                }}
            >
                <Box>
                    <Box
                        sx={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "space-between",
                            mb: { xs: 0.25, sm: 0.5 },
                        }}
                    >
                        <Typography
                            variant="subtitle2"
                            sx={{
                                color: "#2DD4BF",
                                fontWeight: notification.isRead ? 400 : 600,
                                fontSize: "0.875rem",
                            }}
                        >
                            {notification.title}
                        </Typography>

                        {notification.isFavorite && <ArrowUp size={16} color="#2DD4BF" fill="#2DD4BF" />}
                    </Box>

                    <Typography
                        variant="body2"
                        sx={{
                            color: "white",
                            mb: { xs: 0.25, sm: 0.5 },
                            lineHeight: { xs: 1.3, sm: 1.5 },
                            fontSize: "0.875rem",
                        }}
                    >
                        {notification.content}
                    </Typography>

                    <Typography
                        variant="caption"
                        sx={{
                            color: "rgba(255, 255, 255, 0.5)",
                            display: "block",
                            fontSize: "0.75rem",
                        }}
                    >
                        {notification.createdAt}
                    </Typography>
                </Box>
            </Box>
        </Box>
    )
}

NotificationItem.propTypes = {
    notification: PropTypes.shape({
        id: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
        title: PropTypes.string.isRequired,
        content: PropTypes.string.isRequired,
        createdAt: PropTypes.string.isRequired,
        isRead: PropTypes.bool,
        type: PropTypes.string,
        isFavorite: PropTypes.bool, // represents pinned status
    }).isRequired,
    onDelete: PropTypes.func.isRequired,
    onFavorite: PropTypes.func.isRequired,
}

export default NotificationItem

