import { useState, useCallback, useRef, useEffect } from "react"
import PropTypes from "prop-types"
import { Box, Typography, CircularProgress } from "@mui/material"
import { debounce } from "lodash"

const EmojiInputBox = ({ onInputChange, placeholder }) => {
    const [emojis, setEmojis] = useState([])
    const [currentSearchTerm, setCurrentSearchTerm] = useState("")
    const [page, setPage] = useState(0)
    const [hasMore, setHasMore] = useState(true)
    const [isLoadingMore, setIsLoadingMore] = useState(false)
    const inputRef = useRef(null)
    const emojiContainerRef = useRef(null)
    const loadedEmojiIds = useRef(new Set())

    const fetchEmojis = useCallback(
        debounce(async (searchTerm, pageNum = 0, append = false) => {
            if (!searchTerm || (!append && isLoadingMore)) {
                return
            }

            try {
                setIsLoadingMore(true)
                const response = await fetch(
                    `https://g.tenor.com/v1/search?q=${encodeURIComponent(
                        searchTerm,
                    )}&key=${process.env.REACT_APP_TENOR_API_KEY}&limit=20&pos=${pageNum * 20}&contentfilter=low`,
                )
                const data = await response.json()

                const newEmojis = (data.results || []).filter((emoji) => !loadedEmojiIds.current.has(emoji.id))

                newEmojis.forEach((emoji) => loadedEmojiIds.current.add(emoji.id))

                setEmojis((prev) => (append ? [...prev, ...newEmojis] : newEmojis))
                setHasMore(newEmojis.length > 0)
                setCurrentSearchTerm(searchTerm)

                if (!append) {
                    setPage(0)
                    loadedEmojiIds.current.clear()
                    newEmojis.forEach((emoji) => loadedEmojiIds.current.add(emoji.id))
                }
            } catch (error) {
                console.error("Error fetching emojis:", error)
            } finally {
                setIsLoadingMore(false)
            }
        }, 300),
        [],
    )

    const handleScroll = useCallback(() => {
        if (!emojiContainerRef.current || isLoadingMore || !hasMore) return

        const container = emojiContainerRef.current
        const scrollPosition = container.scrollTop + container.clientHeight
        const scrollThreshold = container.scrollHeight - 20

        if (scrollPosition >= scrollThreshold) {
            const nextPage = page + 1
            setPage(nextPage)
            fetchEmojis(currentSearchTerm, nextPage, true)
        }
    }, [fetchEmojis, page, hasMore, isLoadingMore, currentSearchTerm])

    useEffect(() => {
        const container = emojiContainerRef.current

        if (container) {
            container.addEventListener("scroll", handleScroll)
            return () => container.removeEventListener("scroll", handleScroll)
        }
    }, [handleScroll])

    const handleInputChange = (e) => {
        const selection = window.getSelection()
        const range = selection.getRangeAt(0)
        const text = e.target.textContent

        const words = text.split(/\s+/)
        const cursorPosition = range.startOffset
        const currentWordStart = text.lastIndexOf(" ", cursorPosition - 1) + 1
        const currentWord = text.slice(currentWordStart, cursorPosition)

        if (currentWord) {
            fetchEmojis(currentWord)
        } else {
            setEmojis([])
            setCurrentSearchTerm("")
            setPage(0)
            loadedEmojiIds.current.clear()
        }

        onInputChange(e.target.innerHTML)
    }

    const insertEmoji = (emoji) => {
        if (!inputRef.current) return

        const selection = window.getSelection()
        const range = selection.getRangeAt(0)

        const text = inputRef.current.textContent
        const currentWordStart = text.lastIndexOf(" ", range.startOffset - 1) + 1

        const img = document.createElement("img")
        img.src = emoji.media[0].gif.url
        img.alt = emoji.content_description
        img.style.height = "80px"
        img.style.verticalAlign = "middle"
        img.style.margin = "0 4px"
        img.style.objectFit = "contain"

        range.setStart(range.startContainer, currentWordStart)
        range.deleteContents()
        range.insertNode(img)

        const space = document.createTextNode(" ")
        range.setStartAfter(img)
        range.insertNode(space)

        range.setStartAfter(space)
        range.collapse(true)
        selection.removeAllRanges()
        selection.addRange(range)

        setEmojis([])
        inputRef.current.focus()
        onInputChange(inputRef.current.innerHTML)
    }

    return (
        <Box sx={{ position: "relative" }}>
            <Typography
                variant="body2"
                sx={{
                    color: "rgba(255, 255, 255, 0.7)",
                    mb: 1,
                    ml: 1,
                }}
            >
                {placeholder}
            </Typography>

            <Box
                ref={inputRef}
                contentEditable
                suppressContentEditableWarning
                onInput={handleInputChange}
                sx={{
                    minHeight: "100px",
                    maxHeight: "400px",
                    overflowY: "auto",
                    p: 2,
                    border: "1px solid rgba(255, 255, 255, 0.1)",
                    borderRadius: 1,
                    color: "white",
                    outline: "none",
                    transition: "min-height 0.2s ease",
                    "&:hover": {
                        borderColor: "#2DD4BF",
                    },
                    "&:focus": {
                        borderColor: "#2DD4BF",
                    },
                    "& img": {
                        height: "80px",
                        verticalAlign: "middle",
                        margin: "0 4px",
                        objectFit: "contain",
                    },
                }}
            />

            {emojis.length > 0 && (
                <Box
                    ref={emojiContainerRef}
                    sx={{
                        position: "absolute",
                        top: "100%",
                        left: 0,
                        right: 0,
                        zIndex: 1000,
                        mt: 1,
                        p: 1,
                        backgroundColor: "rgba(26, 27, 30, 0.95)",
                        backdropFilter: "blur(10px)",
                        border: "1px solid rgba(255, 255, 255, 0.1)",
                        borderRadius: 1,
                        maxHeight: "300px",
                        overflowY: "auto",
                        display: "grid",
                        gridTemplateColumns: "repeat(4, 1fr)",
                        gap: 1,
                        "&::-webkit-scrollbar": {
                            width: "6px",
                        },
                        "&::-webkit-scrollbar-track": {
                            background: "rgba(255, 255, 255, 0.1)",
                            borderRadius: "3px",
                        },
                        "&::-webkit-scrollbar-thumb": {
                            background: "rgba(45, 212, 191, 0.5)",
                            borderRadius: "3px",
                            "&:hover": {
                                background: "rgba(45, 212, 191, 0.7)",
                            },
                        },
                    }}
                >
                    {emojis.map((emoji) => (
                        <Box
                            key={emoji.id}
                            component="img"
                            src={emoji.media[0].gif.url}
                            alt={emoji.content_description}
                            onClick={() => insertEmoji(emoji)}
                            sx={{
                                width: "100%",
                                height: "80px",
                                objectFit: "contain",
                                cursor: "pointer",
                                borderRadius: "4px",
                                transition: "transform 0.2s",
                                "&:hover": {
                                    transform: "scale(1.1)",
                                },
                            }}
                        />
                    ))}

                    {isLoadingMore && (
                        <Box
                            sx={{
                                gridColumn: "1 / -1",
                                display: "flex",
                                justifyContent: "center",
                                p: 2,
                            }}
                        >
                            <CircularProgress size={24} sx={{ color: "#2DD4BF" }} />
                        </Box>
                    )}
                </Box>
            )}
        </Box>
    )
}

EmojiInputBox.propTypes = {
    onInputChange: PropTypes.func.isRequired,
    placeholder: PropTypes.string,
}

EmojiInputBox.defaultProps = {
    placeholder: "Type your message...",
}

export default EmojiInputBox

