import { Typography } from "@mui/material"
import { Email, Phone, Lock } from "@mui/icons-material"
import SettingSection from "../components/SettingSection"
import AvatarSettingCard from "../components/AvatarSettingCard"

import { EmailSettingDialog, PhonenumberSettingDialog, PasswordSettingDialog } from "./AccoutSectionDailogs"
import { useState } from "react"

const AccountSection = () => {
    const [emailSettingDialogOpen, setEmailSettingDialogOpen] = useState(false)
    const [PhonenumberSettingDialogOpen, setPhonenumberSettingDialogOpen] = useState(false)
    const [PasswordSettingDialogOpen, setPasswordSettingDialogOpen] = useState(false)

    return (
        <>
            <Typography
                variant="h6"
                sx={{
                    mb: 2,
                    color: "text.primary",
                    fontWeight: 600,
                }}
            >
                Account Settings
            </Typography>

            <AvatarSettingCard />

            <SettingSection
                icon={Email}
                title="Email Address"
                value="user@example.com"
                action="edit"
                onClick={() => setEmailSettingDialogOpen(true)}
            />

            <SettingSection
                icon={Phone}
                title="Phone Number"
                value="+1 (555) 123-4567"
                action="edit"
                onClick={() => setPhonenumberSettingDialogOpen(true)}
            />

            <SettingSection
                icon={Lock}
                title="Password"
                value="Last changed 3 months ago"
                action="edit"
                onClick={() => setPasswordSettingDialogOpen(true)}
            />

            <EmailSettingDialog open={emailSettingDialogOpen} onClose={() => setEmailSettingDialogOpen(false)} />

            <PhonenumberSettingDialog
                open={PhonenumberSettingDialogOpen}
                onClose={() => setPhonenumberSettingDialogOpen(false)}
            />

            <PasswordSettingDialog open={PasswordSettingDialogOpen} onClose={() => setPasswordSettingDialogOpen(false)} />
        </>
    )
}

export default AccountSection

